<?php
require_once __DIR__.'/../includes/functions.php';$u=require_auth();$ok=$err=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['_csrf']??null);$action=$_POST['action']??'';
if($action==='profile'){ $name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');if(strlen($name)<2||!preg_match('/^[A-Za-z0-9_]{3,30}$/',$username))$err='Invalid name or username.';else{$st=db()->prepare('SELECT id FROM users WHERE (username=? AND id<>?)');$st->execute([$username,$u['id']]);if($st->fetch())$err='Username already in use.';else{db()->prepare('UPDATE users SET full_name=?,username=?,updated_at=NOW() WHERE id=?')->execute([$name,$username,$u['id']]);$ok='Profile updated.';$u=current_user();}}}
elseif($action==='password'){ $old=$_POST['old_password']??'';$new=$_POST['new_password']??'';if(!$u['password']||!password_verify($old,$u['password'])||strlen($new)<8)$err='Current password is wrong or the new password is too short.';else{db()->prepare('UPDATE users SET password=?,updated_at=NOW() WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$u['id']]);$ok='Password changed.';}}
}
include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/sidebar.php';?><div class="app-shell"><div class="main"><?php include __DIR__.'/../includes/navbar.php';?><section class="page-wrap"><div class="page-heading"><div><span class="eyebrow">ACCOUNT</span><h1>Settings</h1><p>Manage your profile and login settings.</p></div></div><?php if($ok):?><div class="alert alert-success"><?=e($ok)?></div><?php endif;?><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><div class="content-grid"><div class="panel"><h2 class="mb-4">Profile</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="profile"><label>Full name</label><input class="form-control mb-3" name="full_name" value="<?=e($u['full_name'])?>" required><label>Username</label><input class="form-control mb-3" name="username" value="<?=e($u['username'])?>" required><label>Email</label><input class="form-control mb-3" value="<?=e($u['email'])?>" disabled><label>Authentication</label><input class="form-control mb-3" value="<?=e($u['auth_provider'])?>" disabled><button class="btn btn-primary">Save profile</button></form></div><div class="panel"><h2 class="mb-4">Password</h2><?php if($u['password']):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="password"><label>Current password</label><input class="form-control mb-3" type="password" name="old_password" required><label>New password</label><input class="form-control mb-3" type="password" name="new_password" minlength="8" required><button class="btn btn-primary">Change password</button></form><?php else:?><p class="muted">This account uses Google sign-in. Set a local password through the reset flow if needed.</p><?php endif;?></div></div></section></div></div><?php include __DIR__.'/../includes/footer.php';?>
